//! The subset, read back by fontTools.
//!
//! Our own parser loading our own subset proves very little: a wrong idea of
//! where `loca` ends or how the table directory is padded would be shared by
//! both halves, and they would agree perfectly. That is the shape this
//! repository keeps hitting — a zstd encoder that agreed with its own decoder,
//! Anki fixtures generated by the code they tested.
//!
//! So the subset is handed to **fontTools**, which has never seen our
//! assumptions, and asked two questions:
//!
//! 1. Does it load at all — directory, checksums, offsets, `loca` format?
//! 2. Do the retained glyphs still have the **same outlines**, at the **same
//!    glyph ids**, as in the original font?
//!
//! The second is the one that matters. A subset that loads but whose glyphs
//! are shifted by one produces a document full of the wrong letters, and every
//! structural check passes.
//!
//! Glyph *names* are not compared. They live in `post`, which the subset drops
//! because PDF `Identity-H` addresses glyphs by id and never asks for a name;
//! fontTools then synthesises names from `cmap`, so `CR` comes back as
//! `uni000D`. A shifted id would still be caught, since the outline at that id
//! would differ.
//!
//! ## Absence is a failure, not a skip
//!
//! Missing fontTools fails these tests rather than skipping them, matching the
//! `qpdf` and poppler gates. An oracle that skips reports green while checking
//! nothing.

use std::collections::BTreeSet;
use std::process::Command;

fn python() -> String {
    std::env::var("FONTTOOLS_PYTHON").unwrap_or_else(|_| "python3".to_string())
}

fn require_fonttools() {
    let ok = Command::new(python())
        .args(["-c", "import fontTools"])
        .output()
        .map(|out| out.status.success())
        .unwrap_or(false);
    assert!(
        ok,
        "fontTools is required: it is the independent implementation that reads \
         our subset back. Install with `pip install fonttools`, or point \
         FONTTOOLS_PYTHON at an interpreter that has it."
    );
}

fn fixture(name: &str) -> Vec<u8> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(name);
    std::fs::read(&path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()))
}

/// Ask fontTools to compare the subset against the original, glyph by glyph.
///
/// Returns its stdout, which is `OK` or a description of the first difference.
fn compare_with_fonttools(original: &[u8], subset: &[u8], glyphs: &[u16]) -> String {
    require_fonttools();
    // A directory per CALL. Naming it after the glyph count collided: cargo
    // runs tests in parallel, so two comparisons with the same number of
    // glyphs wrote to the same paths and each read the other's font. That
    // reported a bogus outline mismatch on a subset which was in fact correct
    // -- a fault in the harness masquerading as a fault in the thing measured,
    // which is the worst kind of test bug.
    static NEXT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
    let unique = NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let dir = std::env::temp_dir().join(format!(
        "font-subset-oracle-{unique}-{}",
        std::process::id()
    ));
    std::fs::create_dir_all(&dir).expect("temp dir");
    let original_path = dir.join("original.ttf");
    let subset_path = dir.join("subset.ttf");
    std::fs::write(&original_path, original).expect("write original");
    std::fs::write(&subset_path, subset).expect("write subset");

    let script = r#"
import sys
from fontTools.ttLib import TTFont

original = TTFont(sys.argv[1])
subset = TTFont(sys.argv[2])
ids = [int(x) for x in sys.argv[3].split(",") if x]

o_glyf, s_glyf = original["glyf"], subset["glyf"]
o_order, s_order = original.getGlyphOrder(), subset.getGlyphOrder()

if len(o_order) != len(s_order):
    print(f"glyph count changed: {len(o_order)} -> {len(s_order)}")
    raise SystemExit(0)

for gid in ids:
    # Compared by glyph ID, deliberately NOT by name. Names live in `post`,
    # which the subset drops -- PDF Identity-H addresses glyphs by ID and
    # never asks for a name -- so fontTools synthesises them from cmap and
    # they differ (`CR` becomes `uni000D`). An ID shift would still be caught,
    # because the OUTLINE at that ID would then differ.
    a, b = o_glyf[o_order[gid]], s_glyf[s_order[gid]]
    ca, _, fa = a.getCoordinates(o_glyf)
    cb, _, fb = b.getCoordinates(s_glyf)
    if list(ca) != list(cb) or list(fa) != list(fb):
        print(f"glyph {gid} outline differs: {len(list(ca))} vs {len(list(cb))} points")
        raise SystemExit(0)

print("OK")
"#;
    let script_path = dir.join("compare.py");
    std::fs::write(&script_path, script).expect("write script");

    let ids = glyphs
        .iter()
        .map(u16::to_string)
        .collect::<Vec<_>>()
        .join(",");
    let output = Command::new(python())
        .arg(&script_path)
        .arg(&original_path)
        .arg(&subset_path)
        .arg(&ids)
        .output()
        .expect("run fontTools");
    assert!(
        output.status.success(),
        "fontTools could not read the subset:\n{}",
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8_lossy(&output.stdout).trim().to_string()
}

#[test]
fn fonttools_reads_the_subset_and_the_outlines_are_unchanged() {
    let bytes = fixture("../../../fixtures/fonts/Inter-Regular.ttf");
    let font = font_parser::load(&bytes).expect("load");

    // A simple glyph, a composite one, and .notdef.
    let requested: Vec<u16> = vec![0, 2, 36];
    let result = font_subset::subset(&font, &requested.iter().copied().collect::<BTreeSet<_>>())
        .expect("subset");

    let verdict = compare_with_fonttools(&bytes, &result.font, &requested);
    assert_eq!(verdict, "OK", "fontTools disagrees: {verdict}");
}

/// A composite glyph and everything it draws.
///
/// The interesting case: if the closure missed a component, the composite
/// would reference an emptied glyph and its outline would come back *shorter*
/// rather than wrong-looking — which fontTools sees and a size check does not.
#[test]
fn a_composite_glyph_survives_with_its_components() {
    let bytes = fixture("../../../fixtures/fonts/Inter-Regular.ttf");
    let font = font_parser::load(&bytes).expect("load");

    // Glyph 3 is `Adieresis`, a composite.
    let result = font_subset::subset(&font, &BTreeSet::from([3u16])).expect("subset");
    let retained: Vec<u16> = result.retained.iter().copied().collect();
    assert!(
        retained.len() > 2,
        "expected components to be pulled in, got {retained:?}"
    );

    let verdict = compare_with_fonttools(&bytes, &result.font, &retained);
    assert_eq!(verdict, "OK", "fontTools disagrees: {verdict}");
}

/// The scripts the subsetting is actually for.
///
/// Tamil and Japanese are the case that forces embedding in the first place —
/// nothing in the base-14 fonts can draw either — so a subsetter verified only
/// against Latin would be verified against the easy half.
#[test]
fn subsets_of_tamil_and_japanese_are_readable_too() {
    for (path, glyphs) in [
        (
            "../../../learning/human-languages/_fonts/NotoSansTamil-Static.ttf",
            vec![0u16, 5, 20, 60],
        ),
        (
            "../../../learning/human-languages/_fonts/NotoSansJP-Subset.ttf",
            vec![0u16, 3, 9],
        ),
    ] {
        let bytes = fixture(path);
        let font = font_parser::load(&bytes).expect("load");
        let result = font_subset::subset(&font, &glyphs.iter().copied().collect::<BTreeSet<_>>())
            .expect("subset");

        let retained: Vec<u16> = result.retained.iter().copied().collect();
        let verdict = compare_with_fonttools(&bytes, &result.font, &retained);
        assert_eq!(verdict, "OK", "{path}: fontTools disagrees: {verdict}");
    }
}

/// Dropped glyphs really are gone.
///
/// Without this the suite would pass on a subsetter that copied the font
/// unchanged — every retained outline would match, because everything would.
#[test]
fn glyphs_that_were_not_requested_are_emptied() {
    require_fonttools();
    let bytes = fixture("../../../fixtures/fonts/Inter-Regular.ttf");
    let font = font_parser::load(&bytes).expect("load");
    let result = font_subset::subset(&font, &BTreeSet::from([36u16])).expect("subset");

    let dir = std::env::temp_dir().join(format!("font-subset-oracle-empty-{}", std::process::id()));
    std::fs::create_dir_all(&dir).expect("temp dir");
    let subset_path = dir.join("subset.ttf");
    std::fs::write(&subset_path, &result.font).expect("write");

    let script = r#"
import sys
from fontTools.ttLib import TTFont
font = TTFont(sys.argv[1])
glyf = font["glyf"]
order = font.getGlyphOrder()
kept = {int(x) for x in sys.argv[2].split(",") if x}
empty = sum(
    1 for gid, name in enumerate(order)
    if gid not in kept and glyf[name].numberOfContours == 0
)
print(f"{empty} {len(order) - len(kept)}")
"#;
    let script_path = dir.join("count.py");
    std::fs::write(&script_path, script).expect("write script");
    let kept = result
        .retained
        .iter()
        .map(u16::to_string)
        .collect::<Vec<_>>()
        .join(",");

    let output = Command::new(python())
        .arg(&script_path)
        .arg(&subset_path)
        .arg(&kept)
        .output()
        .expect("run fontTools");
    assert!(
        output.status.success(),
        "fontTools failed:\n{}",
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut parts = stdout.split_whitespace();
    let empty: usize = parts.next().unwrap().parse().unwrap();
    let dropped: usize = parts.next().unwrap().parse().unwrap();
    assert_eq!(
        empty, dropped,
        "every non-retained glyph should be empty; {empty} of {dropped} are"
    );
    assert!(dropped > 1000, "the fixture should have plenty to drop");
}
